/* Téléchargement du CV qui marche aussi quand le site est ouvert en local (double-clic sur index.html).
   En ligne, le lien normal vers FouadAzzouzi_CV.pdf est utilisé.
   Si tu modifies ton CV, régénère ce fichier (ou supprime-le une fois le site en ligne). */
(function () {
  if (location.protocol !== 'file:') return;
  var B64 = "";
  function dl(e) {
    e.preventDefault();
    var bin = atob(B64), bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    var url = URL.createObjectURL(new Blob([bytes], { type: 'application/pdf' }));
    var a = document.createElement('a');
    a.href = url; a.download = 'FouadAzzouzi_CV.pdf';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
  }
  document.querySelectorAll('a.btn-cv').forEach(function (a) { a.addEventListener('click', dl); });
})();
